Contact | Conseil Provincial de Berkane Contact | Conseil Provincial de Berkane إتصل بنا | المجلس الإقليمي لبركان /* Styles spécifiques à cette page */ .page-header { background: var(--couleur-primaire); color: var(--couleur-blanc); padding: 40px 5%; text-align: center; margin-bottom: 40px; } .page-header h1 { color: var(--couleur-blanc); margin-bottom: 0; } .content-section { padding: 40px 20px; margin-bottom: 40px; background-color: var(--couleur-card-bg); border-radius: 8px; box-shadow: var(--ombre-douce); } .contact-info { display: flex; flex-wrap: wrap; justify-content: space-around; gap: 20px; margin-bottom: 30px; } .contact-info-item { flex: 1 1 300px; text-align: center; padding: 20px; border: 1px solid #eee; border-radius: 8px; background-color: var(--couleur-arriere-plan); } .contact-info-item h3 { color: var(--couleur-secondaire); margin-bottom: 10px; } .contact-info-item p { margin-bottom: 5px; } .contact-form { background-color: var(--couleur-arriere-plan); padding: 30px; border-radius: 8px; box-shadow: var(--ombre-douce); } .contact-form label { display: block; margin-bottom: 5px; font-weight: bold; color: var(--couleur-texte); } .contact-form input[type="text"], .contact-form input[type="email"], .contact-form textarea { width: 100%; padding: 10px; margin-bottom: 15px; border: 1px solid #ccc; border-radius: 4px; font-family: 'Inter', sans-serif; font-size: 1rem; } .contact-form textarea { min-height: 120px; resize: vertical; } .contact-form button { background-color: var(--couleur-primaire); color: var(--couleur-blanc); padding: 10px 20px; border: none; border-radius: 4px; cursor: pointer; font-size: 1rem; transition: background-color 0.3s ease; } .contact-form button:hover { background-color: var(--couleur-secondaire); } .localisation-map { margin-top: 30px; border-radius: 8px; overflow: hidden; box-shadow: var(--ombre-douce); } .localisation-map iframe { width: 100%; height: 400px; border: 0; } Contactez-nous Contactez-nous تواصل معنا Informations de Contact Informations de Contact معلومات الاتصال Adresse Adresse العنوان Caracucho, Rue de Londres, Berkane 63300 Caracucho, Rue de Londres, Berkane 63300 كاراكشو، زنقة لندن, Berkane 63300 Téléphone Téléphone الهاتف [Numéro de Téléphone] Email Email البريد الإلكتروني [Email Officiel] Envoyez-nous un Message Envoyez-nous un Message أرسل لنا رسالة Votre Nom : Votre Nom : اسمك : Votre Email : Votre Email : بريدك الإلكتروني : Sujet : Sujet : الموضوع : Votre Message : Votre Message : رسالتك : Envoyer le Message Envoyer le Message إرسال الرسالة document.addEventListener('DOMContentLoaded', () => { const contactForm = document.querySelector('.contact-form form'); contactForm.addEventListener('submit', (e) => { e.preventDefault(); const name = document.getElementById('name').value; const email = document.getElementById('email').value; const subject = document.getElementById('subject').value; const message = document.getElementById('message').value; const mailtoLink = `mailto:[Email Officiel]?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(`Nom: ${name}
Email: ${email}

Message:
${message}`)}`; window.location.href = mailtoLink; }); });
